<?php
require __DIR__.'/app/bootstrap.php';auth(true);require __DIR__.'/app/actions.php';$title='Quản trị | Phone Corner';require __DIR__.'/app/header.php';
$cats=query('SELECT * FROM categories ORDER BY id')->fetchAll();
$edit=filter_var($_GET['edit']??0,FILTER_VALIDATE_INT)?:0;$p=query('SELECT * FROM products WHERE id=?',[$edit])->fetch()?:['id'=>0,'name'=>'','category_id'=>0,'price'=>10000,'stock'=>0,'compatible'=>'','description'=>'','image'=>'case.svg','active'=>1];
?>
<h1>Quản trị cửa hàng</h1><nav class="mb-4 d-flex gap-3"><a href="#product">Sản phẩm</a><a href="#category">Danh mục</a><a href="#orders">Đơn hàng</a></nav>
<div class="row g-3 mb-4"><?php foreach(['Sản phẩm'=>'SELECT COUNT(*) FROM products','Đơn hàng'=>'SELECT COUNT(*) FROM orders','Doanh thu hoàn thành'=>"SELECT COALESCE(SUM(total),0) FROM orders WHERE status='completed'"] as $label=>$sql): ?><div class="col-md-4"><div class="panel"><p><?= e($label) ?></p><h3><?= $label==='Doanh thu hoàn thành'?money(query($sql)->fetchColumn()):query($sql)->fetchColumn() ?></h3></div></div><?php endforeach; ?></div>
<section class="panel mb-4" id="product"><h2><?= $p['id']?'Sửa sản phẩm #'.$p['id']:'Thêm sản phẩm' ?></h2><form method="post"><?= csrf() ?><input type="hidden" name="action" value="admin_product_save"><input type="hidden" name="id" value="<?= $p['id'] ?>"><div class="row"><div class="col-md-6"><?php field('name','Tên sản phẩm',$p['name']);field('price','Giá bán (VND, số nguyên)',$p['price'],'number');field('stock','Tồn kho',$p['stock'],'number'); ?></div><div class="col-md-6"><?php field('compatible','Dòng máy tương thích',$p['compatible']); ?><label class="form-label d-block">Danh mục<select name="category_id" class="form-select" required><?php foreach($cats as $c): ?><option value="<?= $c['id'] ?>" <?= $p['category_id']==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></label><label class="form-label d-block">Ảnh minh họa<select name="image" class="form-select"><?php foreach(['case.svg'=>'Ốp lưng','charger.svg'=>'Củ sạc','cable.svg'=>'Cáp sạc','audio.svg'=>'Tai nghe','stand.svg'=>'Giá đỡ','glass.svg'=>'Kính cường lực'] as $file=>$label): ?><option value="<?= $file ?>" <?= $p['image']===$file?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label></div></div><label class="form-label d-block">Mô tả<textarea class="form-control" rows="3" name="description"><?= e($p['description']) ?></textarea></label><label class="d-block mb-3"><input type="checkbox" name="active" <?= $p['active']?'checked':'' ?>> Đang bán</label><button class="btn btn-primary">Lưu sản phẩm</button> <a href="admin.php" class="btn btn-outline-secondary">Thêm mới</a></form></section>
<div class="panel table-responsive mb-4"><table class="table"><thead><tr><th>ID</th><th>Sản phẩm</th><th>Giá</th><th>Tồn</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach(query('SELECT * FROM products ORDER BY id DESC')->fetchAll() as $item): ?><tr><td><?= $item['id'] ?></td><td><?= e($item['name']) ?></td><td><?= money($item['price']) ?></td><td><?= $item['stock'] ?></td><td><?= $item['active']?'Đang bán':'Ngừng bán' ?></td><td><a class="btn btn-sm btn-outline-primary" href="admin.php?edit=<?= $item['id'] ?>#product">Sửa</a><form method="post" class="d-inline" onsubmit="return confirm('Xóa sản phẩm? Nếu đã có đơn hàng, sản phẩm sẽ được ẩn.');"><?= csrf() ?><input type="hidden" name="action" value="admin_product_delete"><input type="hidden" name="id" value="<?= $item['id'] ?>"><button class="btn btn-sm btn-outline-danger">Xóa / Ẩn</button></form></td></tr><?php endforeach; ?></tbody></table></div>
<section id="category" class="panel mb-4"><h2>Danh mục</h2><form method="post" class="d-flex gap-2 mb-3"><?= csrf() ?><input type="hidden" name="action" value="admin_category_save"><input type="hidden" name="id" value="0"><input class="form-control" name="name" placeholder="Tên danh mục mới" aria-label="Tên danh mục mới" required><button class="btn btn-primary">Thêm</button></form><?php foreach($cats as $c): ?><div class="d-flex gap-2 mb-2"><form method="post" class="d-flex gap-2 flex-grow-1"><?= csrf() ?><input type="hidden" name="action" value="admin_category_save"><input type="hidden" name="id" value="<?= $c['id'] ?>"><input class="form-control" aria-label="Tên danh mục" name="name" value="<?= e($c['name']) ?>" required><button class="btn btn-outline-primary">Sửa</button></form><form method="post" onsubmit="return confirm('Xóa danh mục?');"><?= csrf() ?><input type="hidden" name="action" value="admin_category_delete"><input type="hidden" name="id" value="<?= $c['id'] ?>"><button class="btn btn-outline-danger">Xóa</button></form></div><?php endforeach; ?></section>
<section id="orders"><h2>Đơn hàng</h2><?php $nextMap=['pending'=>['confirmed','cancelled'],'confirmed'=>['shipping','cancelled'],'shipping'=>['completed'],'completed'=>[],'cancelled'=>[]];foreach(query('SELECT o.*,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC')->fetchAll() as $o): ?><article class="panel mb-3"><h3>Đơn #<?= $o['id'] ?> · <?= money($o['total']) ?></h3><p><?= e($o['receiver']) ?> — <?= e($o['phone']) ?> — <?= e($o['email']) ?><br><?= e($o['address']) ?><br><?= e($o['created_at']) ?> · <strong><?= e(STATUSES[$o['status']]) ?></strong></p><ul><?php foreach(query('SELECT * FROM order_items WHERE order_id=?',[$o['id']])->fetchAll() as $i): ?><li><?= e($i['product_name']) ?> × <?= $i['quantity'] ?> — <?= money($i['price']*$i['quantity']) ?></li><?php endforeach; ?></ul><?php if($nextMap[$o['status']]): ?><form method="post" class="d-flex gap-2"><?= csrf() ?><input type="hidden" name="action" value="admin_status"><input type="hidden" name="id" value="<?= $o['id'] ?>"><select class="form-select" name="status" aria-label="Trạng thái mới"><?php foreach($nextMap[$o['status']] as $status): ?><option value="<?= $status ?>"><?= e(STATUSES[$status]) ?></option><?php endforeach; ?></select><button class="btn btn-primary">Cập nhật</button></form><?php endif; ?></article><?php endforeach; ?></section>
<?php require __DIR__.'/app/footer.php'; ?>
